import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

const Catalog = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [loading, setLoading] = useState(true);
  
  const navigate = useNavigate();

  const fetchCatalogData = async (searchQuery = '', categoryId = '') => {
    setLoading(true);
    try {
      let url = 'products/?';
      if (searchQuery) url += `search=${searchQuery}&`;
      if (categoryId) url += `category=${categoryId}&`;

      const [prodRes, catRes] = await Promise.all([
        api.get(url),
        api.get('categories/')
      ]);

      setProducts(prodRes.data.results || prodRes.data);
      setCategories(catRes.data.results || catRes.data);
    } catch (err) {
      console.error('Ошибка загрузки каталога', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCatalogData();
  }, []);

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    fetchCatalogData(search, selectedCategory);
  };

  const handleCategoryChange = (catId) => {
    setSelectedCategory(catId);
    fetchCatalogData(search, catId);
  };

  return (
    <div style={{ maxWidth: '1200px', margin: '40px auto', padding: '0 20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px', flexWrap: 'wrap', gap: '20px' }}>
        <h2 style={{ margin: 0, fontSize: '28px', color: '#1a1a1a' }}>Каталог товаров</h2>
        
        <form onSubmit={handleSearchSubmit} style={{ display: 'flex', gap: '10px' }}>
          <input 
            type="text" 
            placeholder="Поиск товаров..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ padding: '10px 14px', width: '280px', borderRadius: '8px', border: '1px solid #ced4da', outline: 'none' }}
            onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
            onBlur={(e) => e.target.style.borderColor = '#ced4da'}
          />
          <button 
            type="submit" 
            style={{ padding: '10px 20px', background: '#F59E0B', color: '#1a1a1a', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', transition: 'background 0.2s' }}
            onMouseEnter={(e) => e.target.style.background = '#E08E0B'}
            onMouseLeave={(e) => e.target.style.background = '#F59E0B'}
          >
            Найти
          </button>
        </form>
      </div>

      {/* Фильтр по категориям */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '30px', overflowX: 'auto', paddingBottom: '5px' }}>
        <button 
          onClick={() => handleCategoryChange('')}
          style={{ 
            padding: '8px 16px', 
            borderRadius: '20px', 
            border: '1px solid #eaeaea', 
            background: selectedCategory === '' ? '#F59E0B' : '#fff', 
            color: selectedCategory === '' ? '#1a1a1a' : '#555',
            fontWeight: '600',
            cursor: 'pointer',
            boxShadow: '0 2px 4px rgba(0,0,0,0.02)'
          }}
        >
          Все категории
        </button>
        {categories.map((cat) => (
          <button 
            key={cat.id}
            onClick={() => handleCategoryChange(cat.id)}
            style={{ 
              padding: '8px 16px', 
              borderRadius: '20px', 
              border: '1px solid #eaeaea', 
              background: Number(selectedCategory) === cat.id ? '#F59E0B' : '#fff', 
              color: Number(selectedCategory) === cat.id ? '#1a1a1a' : '#555',
              fontWeight: '600',
              cursor: 'pointer',
              boxShadow: '0 2px 4px rgba(0,0,0,0.02)'
            }}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: '60px', color: '#666', fontSize: '16px' }}>Загрузка каталога...</div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '20px' }}>
          {products.length > 0 ? (
            products.map((product) => (
              <div 
                key={product.id} 
                onClick={() => navigate(`/products/${product.id}`)}
                style={{ 
                  border: '1px solid #eaeaea', 
                  borderRadius: '16px', 
                  padding: '24px', 
                  background: '#fff', 
                  boxShadow: '0 4px 16px rgba(0,0,0,0.03)',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'space-between',
                  cursor: 'pointer',
                  transition: 'transform 0.2s, box-shadow 0.2s'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-3px)';
                  e.currentTarget.style.boxShadow = '0 8px 24px rgba(0,0,0,0.06)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 4px 16px rgba(0,0,0,0.03)';
                }}
              >
                <div>
                  <h3 style={{ margin: '0 0 10px 0', fontSize: '18px', color: '#1a1a1a' }}>{product.title}</h3>
                  <p style={{ color: '#6c757d', fontSize: '14px', lineHeight: '1.5', marginBottom: '20px', height: '42px', overflow: 'hidden' }}>
                    {product.description}
                  </p>
                </div>
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                    <span style={{ fontWeight: 'bold', fontSize: '20px', color: '#16a34a' }}>{product.price} ₾</span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '12px', color: '#adb5bd', borderTop: '1px solid #f8f9fa', paddingTop: '12px' }}>
                    <span>Продавец: {product.owner?.username || 'Магазин'}</span>
                    <span>{new Date(product.created_at).toLocaleDateString()}</span>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '60px', color: '#666', background: '#fff', borderRadius: '16px', border: '1px solid #eaeaea' }}>
              <p style={{ fontSize: '16px', margin: 0 }}>Товары не найдены</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default Catalog;
